const input = $json.body ?? {};
const email = String(input.email ?? '').trim().toLowerCase();
const accountId = String(input.accountId ?? '').trim();
const comment = String(input.comment ?? '').trim();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('A valid email is required.');
if (!accountId) throw new Error('A confirmed client is required.');
if (!comment) throw new Error('A comment is required.');
return [{json:{email,accountId,comment,videoUrl:String(input.videoUrl ?? ''),videoTitle:String(input.videoTitle ?? ''),channelID:String(input.channelID ?? ''),actorID:String(input.actorID ?? '')}}];

if (!$json.id || !$json.system_prompt) throw new Error('This email is not assigned to the selected client.');
const request = $('Validate reply request').item.json;
return [{json:{...request,clientName:$json.name,systemPrompt:$json.system_prompt}}];

