const response = $json.response ?? $json;
const content = response.output?.flatMap(item => item.content ?? []).find(item => item?.text !== undefined)?.text ?? response.output_text ?? response.content ?? response.text ?? response;
let result = content;
if (typeof result === 'string') { try { result = JSON.parse(result); } catch {} }
const reply = String(result?.reply ?? '').trim();
if (!reply) throw new Error('The OpenAI node did not return a JSON reply.');
return [{json:{reply}}];
